public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<int[]> permutations = new HashSet<>();

    // Loop through all possible permutations of the input array
    for (int[] permutation : permutations(A)) {
        // Check if the permutation is a square array
        boolean isSquare = true;
        for (int i = 0; i < permutation.length - 1; i++) {
            if (permutation[i] + permutation[i + 1] != 0 && Math.sqrt(permutation[i] + permutation[i + 1]) != Math.floor(Math.sqrt(permutation[i] + permutation[i + 1]))) {
                isSquare = false;
                break;
            }
        }

        // If the permutation is a square array, add it to the set
        if (isSquare) {
            permutations.add(permutation);
        }
    }

    // Return the number of square permutations
    return permutations.size();
}

// Generate all possible permutations of the input array
private static List<int[]> permutations(int[] A) {
    List<int[]> permutations = new ArrayList<>();
    permutations.add(A);
    for (int i = 0; i < A.length; i++) {
        int[] newPermutation = new int[A.length];
        for (int j = 0; j < A.length; j++) {
            if (j == i) {
                newPermutation[j] = A[i];
            } else {
                newPermutation[j] = A[j];
            }
        }
        permutations.add(newPermutation);
    }
    return permutations;
}
