public static boolean isBoomerang(int[][] points) {
    // Check if the points are valid
    if (points.length != 3) {
        throw new IllegalArgumentException("Invalid number of points");
    }

    // Calculate the determinant of the matrix formed by the points
    int determinant = determinant(points);

    // Check if the determinant is non-zero
    if (determinant == 0) {
        return false;
    }

    // Calculate the product of the lengths of the sides of the triangle formed by the points
    int product = product(points);

    // Check if the product is negative
    if (product < 0) {
        return true;
    }

    return false;
}

private static int determinant(int[][] points) {
    // Calculate the determinant of the matrix formed by the points
    int determinant = points[0][0] * points[1][1] * points[2][2];
    determinant += points[0][1] * points[1][2] * points[2][0];
    determinant += points[0][2] * points[1][0] * points[2][1];
    determinant -= points[0][2] * points[1][1] * points[2][0];
    determinant -= points[0][1] * points[1][0] * points[2][2];
    determinant -= points[0][0] * points[1][2] * points[2][1];
    return determinant;
}

private static int product(int[][] points) {
    // Calculate the product of the lengths of the sides of the triangle formed by the points
    int product = (points[1][0] - points[0][0]) * (points[2][1] - points[0][1]);
    product -= (points[1][1] - points[0][1]) * (points[2][0] - points[0][0]);
    return product;
}
